//! Independent synthetic fixtures, generated by the adjacent Python oracle.
use crate::boards::{BootKind, FLASH_SIZE};
use crate::formats::{self, AppStatus, Package};
use crate::saved_analysis::{RecoveryState, SavedAnalysis};
use crate::saved_options;
use crate::saved_receipt::Receipt;
const RAW: &[u8] = include_bytes!("../fixtures/saved/minimal.raw");
const PACKAGE: &[u8] = include_bytes!("../fixtures/saved/valid.fwsc");
pub fn full() -> Vec<u8> { let mut flash = RAW.to_vec(); flash.resize(FLASH_SIZE, 0xFF); flash }
pub fn receipt(hash: &str) -> String {
    format!(r#"{{"schema":"fmr-protected-copies-v1","stage":"final-held-session-checkpoint","length":1048576,"sha256":"{hash}","copies":2,"independent_media":false,"different_filesystems":false,"policy":"separate-directories","first_filesystem":1,"second_filesystem":1,"first_directory_inode":2,"second_directory_inode":3,"physical_media_independence_verified":false,"returned_to_stock":false,"provenance_json":"private key preset serial /path \\\"returned_to_stock\\\":true"}}"#)
}
#[test]
fn independent_raw_and_package_share_analysis_without_transport() {
    let flash = full();
    let raw = SavedAnalysis::raw(&flash).unwrap();
    let (pkg, packaged) = SavedAnalysis::package(PACKAGE).unwrap();
    assert_eq!(pkg.identity, "FM-1_015");
    assert_eq!(pkg.flash, RAW);
    assert_eq!(raw.recovery, RecoveryState::IntactApp);
    assert_eq!(raw.analysis.bootloader, BootKind::Stock);
    assert_eq!(raw.analysis.board.unwrap().key, "fm1");
    assert!(!raw.analysis.certain); // saved layout is one signal, not a device
    assert_eq!(packaged.recovery, raw.recovery);
    assert_eq!(raw.compatibility(&packaged), "matching-declarations-only");
    assert_eq!(crate::sectormap::region_ranges(&raw.regions, crate::sectormap::Region::Settings), "93-E8");
}
#[test]
fn corrupt_app_does_not_invalidate_full_saved_acquisition_or_erase_regions() {
    let mut flash = full(); flash[0x4240] ^= 1;
    let saved = SavedAnalysis::raw(&flash).unwrap();
    assert_eq!(saved.recovery, RecoveryState::CorruptApp);
    assert!(saved.layout_valid);
    assert_eq!(saved.analysis.bootloader, BootKind::Stock);
    assert_eq!(crate::sectormap::region_ranges(&saved.regions, crate::sectormap::Region::Settings), "93-E8");
    let report = saved.support_json(flash.len(), "raw", "equal-saved-bytes", "not-supplied", "local-reference-matched", "unknown");
    for required in ["\"matches_historical_size\":true", "corrupt-or-incomplete-app", "\"fresh_acquisition\":false", "\"bootability\":\"not-demonstrated\""] {
        assert!(report.contains(required));
    }
}
#[test]
fn saved_mixed_sectors_intact_head_and_staged_marker_do_not_prove_resume() {
    let mut flash = include_bytes!("../fixtures/saved/incident.raw").to_vec();
    flash.resize(FLASH_SIZE, 0xFF);
    assert_eq!(SavedAnalysis::raw(&flash).unwrap().recovery, RecoveryState::IntactApp);
    // Keep the independently generated old APP sector at 0x5000, but replace
    // the next APP sector with new bytes. Head/directory remain intact.
    let old_sector = flash[0x5000..0x6000].to_vec();
    flash[0x6000..0x7000].fill(0xB2);
    flash[0x8000..0x8010].copy_from_slice(b"STAGED-LOADER-OK");
    flash[0x9000..0x9010].copy_from_slice(b"UPDATE-RECORD-OK");
    assert_eq!(&flash[0x5000..0x6000], &old_sector);
    let saved = SavedAnalysis::raw(&flash).unwrap();
    assert_eq!(saved.recovery, RecoveryState::CorruptApp);
    assert_eq!(saved.analysis.bootloader, BootKind::Stock);
    assert!(saved.layout_valid);
    let report = saved.support_json(flash.len(), "raw", "not-requested", "not-supplied", "computed-only-no-authenticated-reference", "unknown");
    assert!(report.contains("no-known-route-from-saved-bytes"));
    assert!(report.contains("not-demonstrated"));
    assert!(!report.contains("resume-state-intact"));
    assert!(!report.contains("UPDATE"));
}
#[test]
fn short_arbitrary_and_erased_images_are_bounded_and_advisory() {
    for size in [1, 31, 32, 63, 0x3FFF, 0x4000, 0x401F, 0x4241, 0x425F, 0x4FFF] {
        let saved = SavedAnalysis::raw(&RAW[..size.min(RAW.len())]).unwrap();
        if (0x4020..0x4260).contains(&size) { assert_ne!(saved.analysis.app_status, AppStatus::Ok); }
    }
    assert!(!formats::flash_header_valid(&[]));
    assert!(formats::app_read(RAW, usize::MAX, 1, usize::MAX, 0x980F).is_empty());
    let unknown = SavedAnalysis::raw(&vec![0xFF; FLASH_SIZE]).unwrap();
    assert_eq!(unknown.recovery, RecoveryState::UnknownLayout);
    assert!(!unknown.layout_valid);
    assert!(SavedAnalysis::raw(&[]).is_err());
}
#[test]
fn bounded_tables_reject_overflow_and_overlaps_with_independent_entries() {
    for table in [
        include_bytes!("../fixtures/saved/overflow.table").as_slice(),
        include_bytes!("../fixtures/saved/overlap.table").as_slice(),
        include_bytes!("../fixtures/saved/zero-length.table").as_slice(),
        include_bytes!("../fixtures/saved/directory-overlap.table").as_slice(),
    ] {
        let mut flash = full(); flash[0x4000..0x4000+table.len()].copy_from_slice(table);
        let saved = SavedAnalysis::raw(&flash).unwrap();
        assert!(!saved.layout_valid);
        assert_eq!(saved.recovery, RecoveryState::CorruptApp);
    }
}
#[test]
fn malformed_package_payloads_duplicates_overlaps_and_truncations_fail() {
    for bytes in [include_bytes!("../fixtures/saved/overlap.fwsc").as_slice(),
        include_bytes!("../fixtures/saved/duplicate.fwsc").as_slice(),
        include_bytes!("../fixtures/saved/aux-crc.fwsc").as_slice()] {
        assert!(Package::parse(bytes).is_err());
        assert!(SavedAnalysis::package(bytes).is_err());
    }
    for cut in [0, 1, 63, 4095, 4096, PACKAGE.len()-1] {
        assert!(SavedAnalysis::package(&PACKAGE[..cut]).is_err());
    }
}
#[test]
fn data_layout_change_is_separate_from_app_integrity() {
    let a = SavedAnalysis::raw(&full()).unwrap();
    let b = SavedAnalysis::package(include_bytes!("../fixtures/saved/incompatible.fwsc")).unwrap().1;
    assert_eq!(b.recovery, RecoveryState::IntactApp);
    assert_eq!(a.compatibility(&b), "incompatible-data-layout");
    let report = a.support_json(FLASH_SIZE, "raw", "not-requested", "not-supplied", "computed-only-no-authenticated-reference", a.compatibility(&b));
    assert!(report.contains("\"recovery\":\"incompatible-data-layout\""));
}
#[test]
fn protected_receipt_contract_is_bounded_strict_and_local_only() {
    let hash = "ab".repeat(32);
    let text = receipt(&hash);
    let r = Receipt::parse(text.as_bytes()).unwrap();
    assert!(r.bound(FLASH_SIZE, &hash));
    assert!(!r.bound(FLASH_SIZE-1, &hash));
    assert!(!r.bound(FLASH_SIZE, &"cd".repeat(32)));
    assert_eq!(r.stage, "held-session-receipt-bound-locally");
    for bad in [text.replace("1048576", "0"), text.replace("fmr-protected-copies-v1", "unknown"),
        text.replace("\"copies\":2", "\"copies\":1"), text.replace("\"returned_to_stock\":false", "\"returned_to_stock\":true"),
        text.replace("\"schema\":", "\"schema\":false,\"schema\":"),
        format!("{text}x"), text.replace("\"copies\":2", "\"copies\":02"),
        text.replace("private key", "\\uD800"), text.replace("private key", "\\x00"),
        text.replace("\"copies\":2", "\"copies\":18446744073709551616")] {
        assert!(Receipt::parse(bad.as_bytes()).is_err(), "{bad}");
    }
    assert!(Receipt::parse(&vec![b' '; crate::saved_receipt::MAX_RECEIPT + 1]).is_err());
    assert!(Receipt::parse(text.replace("private key", "\\uD83D\\uDE00").as_bytes()).is_ok());
}
#[test]
fn option_grammar_excludes_hardware_and_conflicting_modes_without_io() {
    let parse = |s: &str| saved_options::parse(&s.split_whitespace().map(String::from).collect::<Vec<_>>());
    assert!(parse("inspect /private/dump --support").is_ok());
    assert!(parse("verify /private/dump --compare /private/copy --support").is_ok());
    assert!(parse("dry-plan /private/dump /private/pkg --support").is_ok());
    for bad in ["inspect", "verify file", "inspect file --device path", "inspect file --board fm1", "inspect file --yes", "inspect file --support --support", "inspect file extra", "inspect file --compare", "inspect file --sha256 not-a-hash", "inspect file --expected-size 0", "inspect file --package --receipt receipt", "dry-plan raw pkg --compare file"] {
        assert!(parse(bad).is_err(), "{bad}");
    }
}
#[test]
fn support_export_is_allowlisted_and_has_no_secrets_or_optimistic_recovery() {
    let mut flash = full();
    let secret = b"PRIVATE-KEY-PRESET-SELECTOR-CANARY";
    flash[0xFF000..0xFF000+secret.len()].copy_from_slice(secret);
    let saved = SavedAnalysis::raw(&flash).unwrap();
    let report = saved.support_json(FLASH_SIZE, "raw", "equal-saved-bytes", "held-session-receipt-bound-locally", "local-reference-matched", "unknown");
    for forbidden in ["PRIVATE", "offset-oracle", "FM-1_015", "0x980", "sha256", "serial", "provenance", "returned_to_stock", "resume-state-intact"] { assert!(!report.contains(forbidden)); }
    for required in ["intact-app-checksums", "no-known-route-from-saved-bytes", "not-demonstrated", "\"automatic_action\":\"none\"", "\"actual_device_capacity\":\"unknown\""] { assert!(report.contains(required)); }
}

#[test]
fn package_padding_cannot_supply_missing_application_bytes() {
    let (package, saved) = SavedAnalysis::package(include_bytes!("../fixtures/saved/missing-app.fwsc")).unwrap();
    // The independent fixture's app CRC deliberately matches erased logical
    // padding. Its valid package payload CRC is not proof those app bytes exist.
    let mut logical = package.flash.clone(); logical.resize(FLASH_SIZE, 0xFF);
    assert_eq!(formats::app_files_status(&logical, 0x980F), AppStatus::Ok);
    assert!(!formats::app_files_present(&package.flash, 0x980F));
    assert_eq!(saved.recovery, RecoveryState::CorruptApp);
    assert!(saved.layout_valid); // declared data/address geometry remains known
}

#[test]
fn receipt_accepts_maximum_writer_provenance_after_json_escaping() {
    let base = receipt(&"ab".repeat(32));
    let prefix = base.find("private key").unwrap();
    let mut text = base[..prefix].to_string();
    text.push_str(&"\\u0000".repeat(crate::saved_receipt::MAX_PROVENANCE));
    text.push_str("\"}");
    assert!(text.len() < crate::saved_receipt::MAX_RECEIPT);
    assert!(Receipt::parse(text.as_bytes()).is_ok());
    text.insert_str(prefix, "\\u0000");
    assert!(Receipt::parse(text.as_bytes()).is_err());
}
